import{NextRequest,NextResponse}from'next/server';import{z}from'zod';import{requireActiveAdmin}from'@/lib/admin-auth';import{createAdminClient}from'@/lib/supabase/admin'
const schema=z.object({agreedCost:z.number().nonnegative().nullable().optional(),scheduledDate:z.string().date().nullable().optional(),requirements:z.string().trim().max(4000).nullable().optional(),internalNotes:z.string().trim().max(4000).nullable().optional(),lockVersion:z.number().int().positive()})
export async function PATCH(r:NextRequest,{params}:{params:Promise<{id:string;assignmentId:string}>}){const a=await requireActiveAdmin();if('response'in a)return a.response;const{id,assignmentId}=await params;let body:unknown;try{body=await r.json()}catch{return NextResponse.json({error:'Invalid JSON'},{status:400})}const p=schema.safeParse(body);if(!p.success)return NextResponse.json({error:'Please check the assignment'},{status:400});const db=createAdminClient();const{data:assignment}=await db.from('event_vendor_assignments').select('booking_id').eq('id',assignmentId).maybeSingle();if(!assignment||assignment.booking_id!==id)return NextResponse.json({error:'Vendor assignment not found'},{status:404});const{error}=await db.rpc('update_admin_vendor_assignment',{p_assignment_id:assignmentId,p_agreed_cost:p.data.agreedCost??null,p_scheduled_date:p.data.scheduledDate??null,p_requirements:p.data.requirements??null,p_internal_notes:p.data.internalNotes??null,p_expected_lock_version:p.data.lockVersion,p_admin_id:a.admin.id});return error?NextResponse.json({error:error.message},{status:error.code==='40001'?409:400}):NextResponse.json({ok:true})}
